import sys, os, json, time
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot()
s=r.spec()
q0=np.array([0,1,0,0],float)

def pose(x,y,z): return [x,y,z,*q0]
def send(P,dt=.1,note='',cameras=None,video='none'):
    res=r.submit('ee_pose',np.asarray(P),dt=dt,note=note,cameras=cameras,video=video)
    print(note,'steps',res.meta.get('control_steps_chunk'),'stopped',res.stopped,'tip',res.group('tcp_pose',now=True)[:3], 'plans',str(res.meta.get('plan'))[:500],flush=True)
    return res

def shot(name, cameras=None,depth=False):
    o=r.get_obs(cameras=cameras,depth=depth)
    for c,a in o.last.items(): Image.fromarray(a).save('/app/output/'+name+'_'+c+'.png')
    if depth:
        for c,a in o.last_depth.items():np.save('/app/output/'+name+'_'+c+'_depth.npy',a)
    print('shot',name,'tip',o.group('tcp_pose',now=True)[:3], 'left',o.meta.get('time_left_s'),flush=True)
    return o

if __name__=='__main__':
    send([pose(-.04,0,.15),pose(-.08,0,.18)],dt=.5,note='clear view')
    shot('clear',cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)

PIX=0.227185/1024

def main_pose(u,v,z):
    return pose(-.1+(511.5-v)*PIX,(511.5-u)*PIX,z)

def sample_poly(points,step_px=10):
    out=[]
    for a,b in zip(points[:-1],points[1:]):
        a=np.asarray(a,float); b=np.asarray(b,float)
        n=max(1,int(np.ceil(np.linalg.norm(b[:2]-a[:2])/step_px)))
        out.extend([tuple(a+(b-a)*t/n) for t in range(1,n+1)])
    return out

